[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    private readonly AppDbContext _context;

    public ProductsController(AppDbContext context)
    {
        _context = context;
    }

    [HttpGet("search")]
    public IActionResult Search(
        [FromQuery] string term,
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 10)
    {
        // /api/products/search?term=laptop&page=2&pageSize=20
        var query = _context.Products.AsQueryable();

        if (!string.IsNullOrEmpty(term))
        {
            query = query.Where(p => p.Name.Contains(term));
        }

        var results = query
            .Skip((page - 1) * pageSize)
            .Take(pageSize)
            .ToList();

        return Ok(results);
    }
}

public class SearchParams
{
    [MaxLength(100)]
    public string? Term { get; set; }

    [Range(1, 100)]
    public int Page { get; set; } = 1;

    [Range(1, 50)]
    public int PageSize { get; set; } = 10;

    public bool IncludeInactive { get; set; } = false;
}

[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    private readonly AppDbContext _context;

    public ProductsController(AppDbContext context)
    {
        _context = context;
    }

    [HttpGet("search")]
    public IActionResult Search([FromQuery] SearchParams parameters)
    {
        // /api/products/search?term=laptop&page=1&pageSize=20&includeInactive=true
        // parameters.Term = "laptop"
        // parameters.Page = 1
        // parameters.PageSize = 20
        // parameters.IncludeInactive = true

        var query = _context.Products.AsQueryable();

        if (!string.IsNullOrEmpty(parameters.Term))
        {
            query = query.Where(p => p.Name.Contains(parameters.Term));
        }

        if (!parameters.IncludeInactive)
        {
            query = query.Where(p => p.IsActive);
        }

        var results = query
            .Skip((parameters.Page - 1) * parameters.PageSize)
            .Take(parameters.PageSize)
            .ToList();

        return Ok(results);
    }
}
